package dev.oqthara.runtime;

import java.lang.reflect.InvocationTargetException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Data-record helpers used by generated bytecode. Field reads, writes and construction
 * delegate to the same {@link OqData} and {@link Values} code the interpreter uses, so a
 * compiled program cannot drift from {@code oq run}.
 */
public final class DataValues {
    private DataValues() {
    }

    /** Builds an {@link OqData} from a map of field names to values, preserving order. */
    public static Object make(Object fieldMap, String type) {
        LinkedHashMap<String, Object> values = new LinkedHashMap<>();
        for (Map.Entry<?, ?> entry : ((Map<?, ?>) fieldMap).entrySet()) {
            values.put(String.valueOf(entry.getKey()), entry.getValue());
        }
        return new OqData(type, values);
    }

    @SuppressWarnings("unchecked")
    public static void put(Object map, Object key, Object value) {
        ((Map<Object, Object>) map).put(key, value);
    }

    public static Object get(Object target, String name) {
        if (target instanceof OqData data) {
            if (!data.has(name)) {
                throw new OqError("type " + data.typeName() + " has no field named '" + name + "'",
                        Span.synthetic(),
                        "Available fields: " + String.join(", ", data.fields().keySet()));
            }
            return data.get(name);
        }
        if (target instanceof Map<?, ?> map) {
            return map.get(name);
        }
        JavaField field = readJavaField(target, name);
        if (field.found()) return field.value();
        throw new OqError("cannot read field '" + name + "' on " + Values.typeName(target),
                Span.synthetic());
    }

    private record JavaField(boolean found, Object value) {
    }

    private static final JavaField NOT_FOUND = new JavaField(false, null);

    /**
     * Delegates to {@code JavaBridge.readField}, the interpreter's own interop code, so a
     * compiled field read on a Java object follows exactly the same rules, including which
     * types have no fields at all. This module cannot depend on the interpreter module, which
     * is why the call is reflective.
     */
    private static JavaField readJavaField(Object target, String name) {
        try {
            Class<?> bridge = Class.forName("dev.oqthara.core.JavaBridge");
            Object value = bridge.getMethod("readField", Object.class, String.class, Span.class)
                    .invoke(null, target, name, Span.synthetic());
            if (value == bridge.getField("NOT_FOUND").get(null)) return NOT_FOUND;
            return new JavaField(true, value);
        } catch (InvocationTargetException e) {
            Throwable cause = e.getTargetException();
            if (cause instanceof RuntimeException runtime) throw runtime;
            throw new OqError(String.valueOf(cause), Span.synthetic());
        } catch (ReflectiveOperationException e) {
            return NOT_FOUND;
        }
    }

    public static void set(Object target, Object value, String name) {
        if (target instanceof OqData data) {
            if (!data.has(name)) {
                throw new OqError("type " + data.typeName() + " has no field named '" + name + "'",
                        Span.synthetic());
            }
            data.set(name, value);
            return;
        }
        if (target instanceof Map<?, ?> raw) {
            @SuppressWarnings("unchecked")
            Map<Object, Object> map = (Map<Object, Object>) raw;
            map.put(name, value);
            return;
        }
        throw new OqError("cannot set field '" + name + "' on " + Values.typeName(target),
                Span.synthetic());
    }
}
